{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
d = ImageDraw.Draw(im)
for x in range(0, 2444, 50):
    d.line([(x,0),(x,1292)], fill=(255,0,0) if x%200==0 else (255,150,150), width=2 if x%200==0 else 1)
for y in range(0, 1292, 50):
    d.line([(0,y),(2444,y)], fill=(0,80,255) if y%200==0 else (140,190,255), width=2 if y%200==0 else 1)
for x in range(0, 2444, 200):
    for y in range(0, 1292, 200):
        d.text((x+4,y+4), f"{x},{y}", fill=(255,255,0))
im.crop((1500, 500, 2200, 900)).resize((2100, 1200), Image.LANCZOS).save('g_ll2.png')
im.crop((420, 480, 1000, 800)).resize((1740, 960), Image.LANCZOS).save('g_lr2.png')
print('ok')
